describe('Page Title Update on Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should update page title when navigating between sections', () => {
    // Verify initial page title
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Navigate to a different section
    cy.get('[data-testid="nav-link-section-1"]').click();
    cy.get('[data-testid="page-title"]').should('contain', 'Section 1');

    // Verify title update
    cy.get('[data-testid="page-title"]').should('contain', 'Section 1');

    // Navigate back to dashboard
    cy.get('[data-testid="nav-link-dashboard"]').click();
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Verify title update
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Navigate to another section
    cy.get('[data-testid="nav-link-section-2"]').click();
    cy.get('[data-testid="page-title"]').should('contain', 'Section 2');

    // Verify title update
    cy.get('[data-testid="page-title"]').should('contain', 'Section 2');

    // Navigate back to dashboard
    cy.get('[data-testid="nav-link-dashboard"]').click();
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Verify title update
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');
  });

  it('should handle edge case when navigation fails', () => {
    // Verify initial page title
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Attempt to navigate to a non-existent section
    cy.get('[data-testid="nav-link-section-99"]').click();

    // Verify page title does not change
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Navigation failed');

    // Verify page title remains unchanged
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');
  });
});
